// Wave-N (ADR-039 + ADR-041) test suite — cross-impl byte-equivalence with the
// canonical Rust verifier at `governance/rzl/src/wave_n.rs` and
// `tools/nanorix-verify/src/lib.rs`.
//
// **Forever-Standard discipline (ADR-006 I0):** every test here pins a
// cryptographic-attestation contract. Any divergence from the Rust reference
// vectors is a P0 finding.
//
// Cross-impl reference vectors (generated by
// `cargo run --package nanorix-rzl --example gen_wave_n_vectors`) are
// hard-coded into `TestCrossImplReferenceVector*` tests below.

package auditproof

import (
	"crypto/ed25519"
	"crypto/rand"
	"crypto/sha512"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"strings"
	"testing"
)

const (
	waveNTimestamp = "2026-05-12T00:00:00Z"
	waveNCapsuleID = "cap_wave_n_fixture"
)

// ─────────────────────────────────────────────────────────────────────────────
// Cross-impl reference-vector regression
//
// These hashes are generated by the canonical Rust implementation at
// `governance/rzl/src/wave_n.rs` via the
// `governance/rzl/examples/gen_wave_n_vectors` example. Any Go-side drift from
// these values is a Forever-Standard ADR-006 I0 violation.
// ─────────────────────────────────────────────────────────────────────────────

func TestCrossImplReferenceVectorGenesisHash(t *testing.T) {
	// SHA-512 of the empty string. Mirror of Rust constant
	// `nanorix_rzl::wave_n::GENESIS_SHA512_HEX`.
	const wantGenesis = "cf83e1357eefb8bdf1542850d66d8007d620e4050b5715dc83f4a921d36ce9ce47d0d13c5d85f2b0ff8318d2877eec2f63b931bd47417a81a538327af927da3e"
	if NanorixGenesisHash != wantGenesis {
		t.Fatalf("GENESIS_SHA512_HEX drift: got %s, want %s", NanorixGenesisHash, wantGenesis)
	}
}

func TestCrossImplReferenceVectorMerklePairHash(t *testing.T) {
	// Vector 1: MerklePairHash("aaa", "bbb") ==
	//   SHA-512("aaa" || \x00 || "bbb") in hex.
	const wantAaaBbb = "04ed285cc0e9fe4331e8248f8c37601f4a0836fe1b712fd45096ddd9acdcac1f088ce35db15a93bbc9d13bd7683a2483ab0adbda35814d17f1d44942bf9bd264"
	if got := MerklePairHash("aaa", "bbb"); got != wantAaaBbb {
		t.Errorf("MerklePairHash(aaa, bbb) drift: got %s, want %s", got, wantAaaBbb)
	}

	// Vector 2: deadbeef + cafebabe.
	const wantDeadCafe = "457bce5b50593c263df032ff497826848beaa70fcfb7d9e63ed780f994ed58958ddea9e898f27c3b03a7bc8db879aee658f9ef934bc7c987765fd02b7c6ea978"
	if got := MerklePairHash("deadbeef", "cafebabe"); got != wantDeadCafe {
		t.Errorf("MerklePairHash(deadbeef, cafebabe) drift: got %s, want %s", got, wantDeadCafe)
	}

	// Vector 3: prefix tolerance — sha512:aaa + bbb should equal aaa + bbb.
	if got := MerklePairHash("sha512:aaa", "bbb"); got != wantAaaBbb {
		t.Errorf("MerklePairHash prefix-strip drift: got %s, want %s", got, wantAaaBbb)
	}
}

func TestCrossImplReferenceVectorRecordChainHash(t *testing.T) {
	const wantChain = "sha512:c83d2311b8d3d0d5c20e920773e2e3a56c08bdd2e7d142ce13a0e9702487b679a8cddebb7f4d87b0e1ad7f8d2d2343a0b64f085ae092672c1d2145a1b9653660"
	got := ComputeRecordChainHash(
		"cap_test",
		0,
		"rec_abc",
		"sha512:deadbeef",
		"sha512:cafebabe",
		NanorixGenesisHash,
		nil,
	)
	if got != wantChain {
		t.Errorf("ComputeRecordChainHash basic drift: got %s, want %s", got, wantChain)
	}
}

func TestCrossImplReferenceVectorStep8AmendedAllArms(t *testing.T) {
	prev := NanorixGenesisHash
	ts := "2026-05-12T00:00:00Z"

	cases := []struct {
		name string
		rrmr *string
		ppmr *string
		want string
	}{
		{
			name: "(None, None) — pre-Wave-N legacy byte-equivalent",
			rrmr: nil,
			ppmr: nil,
			want: "3b6a0c8fa70b0e1ead6d2c4c44050c3a45bb732dcd24ff71ffa284a034d5bc41ad4408f4c20649b76ce9a2a8885e857b13ad134f38c92abafb4700b2129b3fbf",
		},
		{
			name: "(Some(sha512:deadbeef), None) — ADR-039 only",
			rrmr: strPtrLocal("sha512:deadbeef"),
			ppmr: nil,
			want: "9e8cd988effabfaf0143a917c9a34f7449290a122babd440db9a3a7983f8783e180f3d0ad1010c5af11ba16d82ff5dd12b102e93ed27f070a1b535fd27509bf1",
		},
		{
			name: "(None, Some(sha512:cafebabe)) — ADR-041 only",
			rrmr: nil,
			ppmr: strPtrLocal("sha512:cafebabe"),
			want: "39b163c4cc38be18dbc4b5b715b1914a738077633a8155f052c2b8e952073ab3b567010673718e4a6f451f9c3eb1bf508e3205cb1fd5a26019f9782ca55113f8",
		},
		{
			name: "(Some, Some) — combined ADR-039 + ADR-041",
			rrmr: strPtrLocal("sha512:deadbeef"),
			ppmr: strPtrLocal("sha512:cafebabe"),
			want: "81c5f049bfb0f7b7e534a297d4d6a8e07704deeb97557827987cf1688a6e189ef07a375c3dcf6d8ad954a0838eecd8c9c5702a6124e8c07a0f1aeffd6e38b844",
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got := ComputeStep8Amended(prev, ts, c.rrmr, c.ppmr)
			if got != c.want {
				t.Errorf("Step 8 %s drift:\n  got=%s\n want=%s", c.name, got, c.want)
			}
		})
	}
}

// ─────────────────────────────────────────────────────────────────────────────
// Forever-Standard byte-equivalence with pre-Wave-N legacy formula
// ─────────────────────────────────────────────────────────────────────────────

func TestStep8AmendedNoneNoneByteEquivalence(t *testing.T) {
	// The LOAD-BEARING test: when neither receipts nor parents present, Step 8
	// MUST be byte-identical to the pre-Wave-N legacy `ComputeStepHash`. Every
	// pre-Wave-N AuditProof on the 100-fixture corpus depends on this.
	prev := NanorixGenesisHash
	ts := "2026-05-12T00:00:00Z"

	legacy := ComputeStepHash(prev, "capsule_destroy", "destroy", "capsule_lifecycle_verification", ts)
	amended := ComputeStep8Amended(prev, ts, nil, nil)

	if legacy != amended {
		t.Fatalf("Forever-Standard violation: (nil, nil) MUST equal legacy formula\n  legacy=%s\n  amended=%s", legacy, amended)
	}
}

func TestStep8AmendedDivergesWithReceiptsPresent(t *testing.T) {
	prev := NanorixGenesisHash
	ts := "2026-05-12T00:00:00Z"

	base := ComputeStep8Amended(prev, ts, nil, nil)
	withRR := ComputeStep8Amended(prev, ts, strPtrLocal("sha512:deadbeef"), nil)
	if base == withRR {
		t.Fatalf("Presence of rrmr MUST shift Step 8 hash")
	}
}

func TestStep8AmendedDivergesWithParentsPresent(t *testing.T) {
	prev := NanorixGenesisHash
	ts := "2026-05-12T00:00:00Z"

	base := ComputeStep8Amended(prev, ts, nil, nil)
	withPP := ComputeStep8Amended(prev, ts, nil, strPtrLocal("sha512:cafebabe"))
	if base == withPP {
		t.Fatalf("Presence of ppmr MUST shift Step 8 hash")
	}
}

func TestStep8AmendedAllArmsDistinct(t *testing.T) {
	prev := NanorixGenesisHash
	ts := "2026-05-12T00:00:00Z"
	rr := "sha512:1111"
	pp := "sha512:2222"

	rrOnly := ComputeStep8Amended(prev, ts, strPtrLocal(rr), nil)
	ppOnly := ComputeStep8Amended(prev, ts, nil, strPtrLocal(pp))
	both := ComputeStep8Amended(prev, ts, strPtrLocal(rr), strPtrLocal(pp))

	if rrOnly == both {
		t.Errorf("rrOnly must differ from both")
	}
	if ppOnly == both {
		t.Errorf("ppOnly must differ from both")
	}
	if rrOnly == ppOnly {
		t.Errorf("rrOnly must differ from ppOnly")
	}
}

func TestStep8AmendedPrefixTolerance(t *testing.T) {
	prev := NanorixGenesisHash
	ts := "2026-05-12T00:00:00Z"

	a := ComputeStep8Amended(prev, ts, strPtrLocal("sha512:deadbeef"), nil)
	b := ComputeStep8Amended(prev, ts, strPtrLocal("deadbeef"), nil)
	if a != b {
		t.Errorf("Prefix tolerance broken:\n  with prefix=%s\n  no prefix=%s", a, b)
	}
}

