func TestMerkleRootN0ReturnsNone(t *testing.T) {
	_, ok := MerkleRootSHA512NullSeparated(nil)
	if ok {
		t.Fatal("N=0 must return (\"\", false)")
	}
}

func TestMerkleRootN1EqualsLeaf(t *testing.T) {
	root, ok := MerkleRootSHA512NullSeparated([]string{"sha512:abc123"})
	if !ok {
		t.Fatal("N=1 must return (leaf, true)")
	}
	if root != "abc123" {
		t.Errorf("N=1 root must equal leaf stripped: got %s, want abc123", root)
	}
}

func TestMerkleRootN2IsPairHash(t *testing.T) {
	root, ok := MerkleRootSHA512NullSeparated([]string{"sha512:aaa", "sha512:bbb"})
	if !ok {
		t.Fatal("N=2 root expected")
	}
	want := MerklePairHash("aaa", "bbb")
	if root != want {
		t.Errorf("N=2 root drift: got %s, want %s", root, want)
	}
}

func TestMerkleRootN3UsesOddDuplication(t *testing.T) {
	// Three leaves: a, b, c
	// Level 0: [a, b, c]
	// Level 1: [pair(a,b), pair(c,c)]
	// Level 2: [pair(pair(a,b), pair(c,c))] = root
	root, ok := MerkleRootSHA512NullSeparated([]string{"aaa", "bbb", "ccc"})
	if !ok {
		t.Fatal("N=3 root expected")
	}
	lvl1Left := MerklePairHash("aaa", "bbb")
	lvl1Right := MerklePairHash("ccc", "ccc")
	want := MerklePairHash(lvl1Left, lvl1Right)
	if root != want {
		t.Errorf("N=3 odd-duplication root drift: got %s, want %s", root, want)
	}
}

func TestMerkleRootDeterministic(t *testing.T) {
	leaves := make([]string, 7)
	for i := range leaves {
		leaves[i] = fmt.Sprintf("leaf_%02d", i)
	}
	r1, ok1 := MerkleRootSHA512NullSeparated(leaves)
	r2, ok2 := MerkleRootSHA512NullSeparated(leaves)
	if !ok1 || !ok2 || r1 != r2 {
		t.Fatalf("Merkle root must be deterministic: r1=%s, r2=%s", r1, r2)
	}
}

func TestMerkleRootReorderBreaksRoot(t *testing.T) {
	leaves := []string{"a", "b", "c", "d", "e"}
	r1, _ := MerkleRootSHA512NullSeparated(leaves)

	leaves[0], leaves[4] = leaves[4], leaves[0]
	r2, _ := MerkleRootSHA512NullSeparated(leaves)
	if r1 == r2 {
		t.Errorf("Leaf reorder must change Merkle root")
	}
}

// ─────────────────────────────────────────────────────────────────────────────
// Inclusion proof
// ─────────────────────────────────────────────────────────────────────────────

func TestInclusionProofN1Empty(t *testing.T) {
	leaves := []string{"sha512:onlyleaf"}
	proof, ok := BuildMerkleInclusionProof(leaves, 0)
	if !ok {
		t.Fatal("BuildMerkleInclusionProof N=1 idx=0 must succeed")
	}
	if len(proof) != 0 {
		t.Errorf("N=1 inclusion proof must be empty, got %d entries", len(proof))
	}
	root, _ := MerkleRootSHA512NullSeparated(leaves)
	if !VerifyMerkleInclusionProof("onlyleaf", 0, proof, root) {
		t.Error("Empty inclusion proof must verify when leaf == root")
	}
}

func TestInclusionProofN2Roundtrips(t *testing.T) {
	leaves := []string{"aaa", "bbb"}
	root, _ := MerkleRootSHA512NullSeparated(leaves)
	p0, _ := BuildMerkleInclusionProof(leaves, 0)
	p1, _ := BuildMerkleInclusionProof(leaves, 1)
	if !VerifyMerkleInclusionProof("aaa", 0, p0, root) {
		t.Error("N=2 leaf 0 inclusion must verify")
	}
	if !VerifyMerkleInclusionProof("bbb", 1, p1, root) {
		t.Error("N=2 leaf 1 inclusion must verify")
	}
	// Wrong leaf must fail.
	if VerifyMerkleInclusionProof("xxx", 0, p0, root) {
		t.Error("Inclusion proof MUST NOT verify for wrong leaf")
	}
}

func TestInclusionProofN10EachLeafRoundtrips(t *testing.T) {
	leaves := make([]string, 10)
	for i := range leaves {
		leaves[i] = fmt.Sprintf("leaf_%03d", i)
	}
	root, _ := MerkleRootSHA512NullSeparated(leaves)
	for i, leaf := range leaves {
		proof, ok := BuildMerkleInclusionProof(leaves, i)
		if !ok {
			t.Fatalf("BuildMerkleInclusionProof idx=%d failed", i)
		}
		if !VerifyMerkleInclusionProof(leaf, i, proof, root) {
			t.Errorf("leaf %d inclusion proof must roundtrip", i)
		}
	}
}

func TestInclusionProofOutOfRangeIsNone(t *testing.T) {
	leaves := []string{"a", "b"}
	if _, ok := BuildMerkleInclusionProof(leaves, 5); ok {
		t.Error("Out-of-range leaf_index must return (_, false)")
	}
}

