// ADR-039 conformance (mirrors Rust `record_chain_hash_pattern_tag_binds`):
// a declared pattern_tag is a SIGNED primitive — it must change the chain
// hash, else it could be swapped without invalidating the signature-anchored
// Merkle ladder.
func TestRecordChainHashPatternTagBinds(t *testing.T) {
	base := ComputeRecordChainHash("cap_x", 0, "rec_a", "sha512:in", "sha512:out", NanorixGenesisHash, nil)
	tagged := ComputeRecordChainHash("cap_x", 0, "rec_a", "sha512:in", "sha512:out", NanorixGenesisHash, strPtrLocal("pa"))
	retagged := ComputeRecordChainHash("cap_x", 0, "rec_a", "sha512:in", "sha512:out", NanorixGenesisHash, strPtrLocal("extraction"))
	if base == tagged {
		t.Errorf("declared tag must bind into the hash")
	}
	if tagged == retagged {
		t.Errorf("different tags must produce different hashes")
	}
}

// "No tag = old bytes": the nil-tag output must equal the manually computed
// pre-fix preimage (no trailing \x00+tag segment). Together with the pinned
// cross-impl vector in TestCrossImplReferenceVectorRecordChainHash this locks
// the untagged formula to its pre-fix byte layout.
func TestRecordChainHashNilTagKeepsPreFixBytes(t *testing.T) {
	preimage := "cap_x\x000\x00rec_a\x00in\x00out\x00" + NanorixGenesisHash
	sum := sha512.Sum512([]byte(preimage))
	want := "sha512:" + hex.EncodeToString(sum[:])
	got := ComputeRecordChainHash("cap_x", 0, "rec_a", "sha512:in", "sha512:out", NanorixGenesisHash, nil)
	if got != want {
		t.Errorf("nil-tag formula drift from pre-fix bytes: got %s, want %s", got, want)
	}
}

