func TestCycleDetectionRejectsSelfReference(t *testing.T) {
	parents := []ParentProofLink{
		{
			ParentChainHash: "sha512:abc",
			ParentKeyID:     "k",
			ParentSignature: "base64:s",
		},
	}
	if got := DetectParentProofCycle(parents, "sha512:abc"); got != 0 {
		t.Errorf("cycle detection must return idx 0; got %d", got)
	}
}

func TestCycleDetectionAcceptsDistinct(t *testing.T) {
	parents := []ParentProofLink{
		{
			ParentChainHash: "sha512:abc",
			ParentKeyID:     "k",
			ParentSignature: "base64:s",
		},
	}
	if got := DetectParentProofCycle(parents, "sha512:xyz"); got != -1 {
		t.Errorf("distinct parent must return -1; got %d", got)
	}
}

func TestCycleDetectionPrefixTolerance(t *testing.T) {
	parents := []ParentProofLink{
		{ParentChainHash: "abc", ParentKeyID: "k", ParentSignature: "base64:s"},
	}
	if DetectParentProofCycle(parents, "sha512:abc") != 0 {
		t.Errorf("prefix tolerance broken (sha512: on self)")
	}
	if DetectParentProofCycle(parents, "abc") != 0 {
		t.Errorf("prefix tolerance broken (bare on self)")
	}
}

// ─────────────────────────────────────────────────────────────────────────────
// Property-style cycle rejection (10 iter — Go iteration is slower than Rust;
// budget is calibrated to remain under 1s in the test harness while still
// exercising the codepath with deterministic input variation)
// ─────────────────────────────────────────────────────────────────────────────

func TestCycleRejection10Iter(t *testing.T) {
	// Deterministic LCG seed; matches the Rust 10k iter pattern at smaller
	// scale to keep Go test wall time bounded.
	var state uint64 = 0xFEEDBEEFDEADC0DE
	next := func() uint64 {
		state = state*6364136223846793005 + 1442695040888963407
		return state
	}

	for iter := 0; iter < 10; iter++ {
		r := next()
		selfHash := fmt.Sprintf("sha512:%x", r)
		parents := []ParentProofLink{
			{
				ParentChainHash: selfHash, // self-reference → cycle
				ParentKeyID:     fmt.Sprintf("k_%d", iter),
				ParentSignature: "base64:malicious",
			},
		}
		if got := DetectParentProofCycle(parents, selfHash); got != 0 {
			t.Errorf("iter %d: cycle MUST fire on self-reference; got %d", iter, got)
		}
	}
}

func TestDepthCapAcceptsAt32(t *testing.T) {
	parents := make([]ParentProofLink, 32)
	for i := range parents {
		parents[i].ParentChainHash = fmt.Sprintf("sha512:p%d", i)
		parents[i].ParentKeyID = fmt.Sprintf("k_%d", i)
		parents[i].ParentSignature = "base64:s"
	}
	if err := EnforceDepthCap(parents); err != nil {
		t.Errorf("Exactly 32 parents must be accepted; got error: %v", err)
	}
}

func TestDepthCapRejectsAt33(t *testing.T) {
	parents := make([]ParentProofLink, 33)
	for i := range parents {
		parents[i].ParentChainHash = fmt.Sprintf("sha512:p%d", i)
		parents[i].ParentKeyID = fmt.Sprintf("k_%d", i)
		parents[i].ParentSignature = "base64:s"
	}
	if err := EnforceDepthCap(parents); err == nil {
		t.Errorf("33 parents must be rejected by depth cap")
	}
}

// ─────────────────────────────────────────────────────────────────────────────
// Mode B — Standalone receipt verification
// ─────────────────────────────────────────────────────────────────────────────

func TestVerifyRecordReceiptModeBHappyPath(t *testing.T) {
	pub, priv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatalf("key gen: %v", err)
	}

	// Build a single-record receipt; N=1 → root = leaf, inclusion proof empty.
	capsuleID := waveNCapsuleID
	in := sha512Sum([]byte("input_data_0"))
	out := sha512Sum([]byte("output_data_0"))
	activityRoot := NanorixGenesisHash
	chainHash := ComputeRecordChainHash(capsuleID, 0, "rec_0", in, out, activityRoot, nil)

	receipt := RecordReceipt{
		RecordIndex:          0,
		RecordID:             "rec_0",
		RecordInputHash:      "sha512:" + in,
		RecordOutputHash:     "sha512:" + out,
		RecordChainHash:      chainHash,
		MerkleInclusionProof: []string{},
	}

	// Outer chain hash arbitrary; signature is over its ASCII-hex bytes.
	outerChainHash := strings.Repeat("a", 128)
	sig := ed25519.Sign(priv, []byte(outerChainHash))
	sigB64 := base64.StdEncoding.EncodeToString(sig)

	opts := VerifyRecordReceiptOptions{
		CapsuleID:         capsuleID,
		OuterMerkleRoot:   chainHash, // N=1 root = leaf
		OuterChainHash:    "sha512:" + outerChainHash,
		OuterSignatureB64: "base64:" + sigB64,
		OuterPublicKey:    pub,
	}
	if err := VerifyRecordReceipt(receipt, opts); err != nil {
		t.Errorf("happy-path Mode B verification must succeed; got: %v", err)
	}
}

func TestVerifyRecordReceiptModeBTaggedHappyPath(t *testing.T) {
	pub, priv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatalf("key gen: %v", err)
	}

	// Tagged single-record receipt; N=1 → root = leaf, inclusion proof empty.
	capsuleID := waveNCapsuleID
	in := sha512Sum([]byte("input_data_tagged"))
	out := sha512Sum([]byte("output_data_tagged"))
	tag := "rcm_claim"
	chainHash := ComputeRecordChainHash(capsuleID, 0, "rec_0", in, out, NanorixGenesisHash, &tag)

	receipt := RecordReceipt{
		RecordIndex:          0,
		RecordID:             "rec_0",
		RecordInputHash:      "sha512:" + in,
		RecordOutputHash:     "sha512:" + out,
		RecordChainHash:      chainHash,
		PatternTag:           &tag,
		MerkleInclusionProof: []string{},
	}

	outerChainHash := strings.Repeat("a", 128)
	sig := ed25519.Sign(priv, []byte(outerChainHash))

	opts := VerifyRecordReceiptOptions{
		CapsuleID:         capsuleID,
		OuterMerkleRoot:   chainHash,
		OuterChainHash:    "sha512:" + outerChainHash,
		OuterSignatureB64: "base64:" + base64.StdEncoding.EncodeToString(sig),
		OuterPublicKey:    pub,
	}
	if err := VerifyRecordReceipt(receipt, opts); err != nil {
		t.Errorf("tagged Mode B verification must succeed; got: %v", err)
	}

	// Tag swap after signing must invalidate the recompute.
	swapped := "custom"
	receipt.PatternTag = &swapped
	if err := VerifyRecordReceipt(receipt, opts); err == nil {
		t.Errorf("swapped pattern_tag MUST be rejected in Mode B")
	}

	// Tag strip must also invalidate (tagged hash != untagged hash).
	receipt.PatternTag = nil
	if err := VerifyRecordReceipt(receipt, opts); err == nil {
		t.Errorf("stripped pattern_tag MUST be rejected in Mode B")
	}
}

