// ─────────────────────────────────────────────────────────────────────────────
// Mode A — Full Wave-N AuditProof verification
// ─────────────────────────────────────────────────────────────────────────────

// buildWaveNProof creates a Wave-N AuditProof with N receipts + M parent
// links, mirroring `tools/nanorix-verify/tests/wave_n_fixtures.rs::
// synthesize_wave_n_proof`.
func buildWaveNProof(nReceipts int, parentSeeds [][]string) map[string]interface{} {
	subsystems := []string{
		"eee_namespace", "eee_tmpfs", "eee_memory", "dire_keys",
		"dire_identity", "fgx_forensic", "rzl_audit", "capsule_destroy",
	}

	// Build receipts.
	receipts := make([]interface{}, 0, nReceipts)
	leafChainHashes := make([]string, 0, nReceipts)
	for i := 0; i < nReceipts; i++ {
		inH := sha512Sum([]byte(fmt.Sprintf("in_%d", i)))
		outH := sha512Sum([]byte(fmt.Sprintf("out_%d", i)))
		activityRoot := NanorixGenesisHash
		recordID := fmt.Sprintf("rec_%05d", i)

		var patternTag string
		switch i % 4 {
		case 0:
			patternTag = "pa"
		case 1:
			patternTag = "rcm_claim"
		case 2:
			patternTag = "dicom_study"
		default:
			patternTag = "agent_step"
		}
		// ADR-039: the declared tag is a signed primitive — bound into the
		// per-record chain hash, not merely carried in the JSON.
		chainH := ComputeRecordChainHash(waveNCapsuleID, uint32(i), recordID, inH, outH, activityRoot, strPtrLocal(patternTag))
		receipts = append(receipts, map[string]interface{}{
			"record_index":           i,
			"record_id":              recordID,
			"record_input_hash":      "sha512:" + inH,
			"record_output_hash":     "sha512:" + outH,
			"record_chain_hash":      chainH,
			"pattern_tag":            patternTag,
			"merkle_inclusion_proof": []string{},
		})
		leafChainHashes = append(leafChainHashes, chainH)
	}

	var rrmrPtr *string
	if len(leafChainHashes) > 0 {
		root, ok := MerkleRootSHA512NullSeparated(leafChainHashes)
		if ok {
			full := "sha512:" + root
			rrmrPtr = &full
		}
	}

	// Build parents.
	parents := make([]interface{}, 0, len(parentSeeds))
	parentLeaves := make([]string, 0, len(parentSeeds))
	for i, seed := range parentSeeds {
		role := seed[0]
		org := seed[1]
		chainH := sha512Sum([]byte(fmt.Sprintf("parent_%d", i)))
		sig := sha512Sum([]byte(fmt.Sprintf("sig_%d", i)))
		parents = append(parents, map[string]interface{}{
			"parent_chain_hash":       "sha512:" + chainH,
			"parent_key_id":           fmt.Sprintf("cust-auth-%s-%d", role, i),
			"parent_signature":        "base64:" + sig,
			"parent_role":             role,
			"parent_jurisdiction":     "US",
			"parent_organization_tag": fmt.Sprintf("vendor:%s", org),
		})
		parentLeaves = append(parentLeaves, "sha512:"+chainH)
	}
	var ppmrPtr *string
	if len(parentLeaves) > 0 {
		root, ok := MerkleRootSHA512NullSeparated(parentLeaves)
		if ok {
			full := "sha512:" + root
			ppmrPtr = &full
		}
	}

	// Build chain steps 1-7 legacy, step 8 amended.
	prevHash := NanorixGenesisHash
	chain := make([]interface{}, 0, 8)
	for i, subsystem := range subsystems {
		method := LookupMethod(subsystem)
		var chainHash string
		if i == 7 {
			chainHash = ComputeStep8Amended(prevHash, waveNTimestamp, rrmrPtr, ppmrPtr)
		} else {
			chainHash = ComputeStepHash(prevHash, subsystem, "destroy", method, waveNTimestamp)
		}
		chain = append(chain, map[string]interface{}{
			"subsystem":  subsystem,
			"method":     method,
			"chain_hash": chainHash,
		})
		prevHash = chainHash
	}
	finalHash := chain[7].(map[string]interface{})["chain_hash"].(string)

	proof := map[string]interface{}{
		"cdp_version":  "1.0",
		"capsule_id":   waveNCapsuleID,
		"destroyed_at": waveNTimestamp,
		"chain":        chain,
		"final_hash":   finalHash,
		"attestation": map[string]interface{}{
			"algorithm":           "Ed25519",
			"signing_key_version": "1",
		},
	}
	if nReceipts > 0 {
		proof["record_receipts"] = receipts
		if rrmrPtr != nil {
			proof["record_receipts_merkle_root"] = *rrmrPtr
		}
	}
	if len(parentSeeds) > 0 {
		proof["parent_proof_hashes"] = parents
		if ppmrPtr != nil {
			proof["parent_proofs_merkle_root"] = *ppmrPtr
		}
	}
	return proof
}

func TestFixture01N0NoReceiptsNoParentsByteEquivalentBaseline(t *testing.T) {
	proof := buildWaveNProof(0, nil)
	jsonBytes, _ := json.Marshal(proof)
	result := VerifyFullAuditProofWaveN(jsonBytes, VerifierPolicy{})
	if !result.Valid {
		t.Fatalf("N=0 Wave-N proof MUST verify (pre-Wave-N baseline); got %+v", result)
	}
	if _, has := proof["record_receipts"]; has {
		t.Errorf("N=0 must NOT carry record_receipts")
	}
	if _, has := proof["parent_proof_hashes"]; has {
		t.Errorf("N=0 must NOT carry parent_proof_hashes")
	}
}

