func TestFixture09CyclicParentRejected(t *testing.T) {
	// Build happy-path proof, then mutate the single parent to be a
	// self-reference. Update parent_proofs_merkle_root so the parent-root
	// check at stage 3 passes; the chain-walk then detects mismatch at step 8.
	proof := buildWaveNProof(1, [][]string{{"input-data", "banjo"}})
	chain := proof["chain"].([]interface{})
	step8 := chain[7].(map[string]interface{})["chain_hash"].(string)

	cyclicParent := map[string]interface{}{
		"parent_chain_hash":       "sha512:" + step8,
		"parent_key_id":           "cust-auth-self-cycle",
		"parent_signature":        "base64:malicious",
		"parent_role":             "self-loop",
		"parent_jurisdiction":     "US",
		"parent_organization_tag": "vendor:cyclic",
	}
	proof["parent_proof_hashes"] = []interface{}{cyclicParent}
	proof["parent_proofs_merkle_root"] = "sha512:" + step8

	jsonBytes, _ := json.Marshal(proof)
	result := VerifyFullAuditProofWaveN(jsonBytes, VerifierPolicy{})
	if result.Valid {
		t.Errorf("Cyclic parent MUST be rejected; got %+v", result)
	}
}

func TestFixture10MissingSignatureParentAcceptedStructurally(t *testing.T) {
	proof := buildWaveNProof(1, [][]string{{"input-data", "banjo"}})
	parents := proof["parent_proof_hashes"].([]interface{})
	p0 := parents[0].(map[string]interface{})
	p0["parent_signature"] = ""

	jsonBytes, _ := json.Marshal(proof)
	result := VerifyFullAuditProofWaveN(jsonBytes, VerifierPolicy{})
	// Wave A scope: per-link signature NOT checked; Merkle root binding intact.
	if !result.Valid {
		t.Errorf("missing-signature parent verifies STRUCTURALLY at Wave A; got %+v", result)
	}
}

